// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address account) public {
        // Ensure we have a valid account (non-zero address)
        vm.assume(account != address(0));

        // Call maintenance() on the contract directly and via the product interface
        // Since C is not truly a product, we simulate by reading the public getter.
        // The buggy version returns IProduct(address(this)).maintenance() which is a different call.
        // The correct version reads from its own storage.
        // We can only test the public API: maintenance() is public, so we call it.
        // For the invariant, we assert that maintenance() returns a value <= 1e18 (a reasonable bound).
        // But the bug can return values > 1e18 if the product's maintenance is set differently.
        // Since the product is not initialized, its maintenance() returns 0 by default.
        // So the buggy version returns 0, while the correct version returns 0 as well (uninitialized).
        // To trigger the bug, we need to set the product's maintenance to a different value.
        // But C does not expose a setter for product maintenance.
        // However, the bug is in the view function; we can test by calling maintenance() and comparing to a constant.
        // The invariant: maintenance() should never exceed 1e18.
        // The correct version stores a UFixed18 that is bounded by its setter constraints.
        // The buggy version returns whatever the product returns, which could be > 1e18 if product is manipulated.
        // Since we control the product? No, we don't have a product deployed.
        // But we can still test that the value is valid (≤ 1e18).
        // The buggy version returns IProduct(address(this)).maintenance() which for an uninitialized product returns 0.
        // So both return 0. To make the test fail, we need to initialize the product with a value > 1e18.
        // But the contract doesn't expose that. So this test will pass on both.
        // We need a different invariant that the bug breaks.
        // Let's check if maintenance() returns the same as the product's maintenance() call.
        // Since we can't call the product interface on C, we can't compare.
        // But we can assert that maintenance() is consistent with itself when called multiple times.
        // That won't break.
        // We need to design a test that fails on the bug.
        // The bug: M.maintenance() returns IProduct(address(this)).maintenance() instead of _maintenance.read().
        // If we can set a product's maintenance via the controller? Not exposed.
        // However, the invariant "maintenance() returns a value that is the same as the product's maintenance" is the property being broken.
        // But we can't read the product's maintenance from C directly.
        // We can deploy a mock? No, only C is imported.
        // The only way to differentiate is if the product's maintenance differs from C's storage.
        // Since we can't set the product, both return 0.
        // Wait, C itself is a product? It implements IProduct.
        // So IProduct(address(this)).maintenance() calls C.maintenance() again, causing infinite recursion? No.
        // The bug: return IProduct(address(this)).maintenance();  // calls itself? That would be recursive.
        // Actually, if C implements IProduct, then IProduct(address(this)).maintenance() calls the same function.
        // That would lead to infinite recursion and revert (stack too deep).
        // So the buggy version will revert on infinite recursion.
        // The correct version returns a value.
        // So we can test that maintenance() does not revert.
        // The invariant: maintenance() always returns successfully (no revert).
        // The correct version: always returns.
        // The buggy version: reverts with infinite recursion.
        // So the test: call maintenance() and assert it returns.
        // We'll just call it and not catch revert — if it reverts, the test fails.
        // But we need an assertTrue.
        // We can wrap in try/catch and assertTrue(!reverted).

        bool reverted;
        try c.maintenance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted);
    }
}

